#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);
    // v[0] = no, v[1] = one, v[2] = both (profit by number of earlier neighbors).
    vector<ll> v[3];
    for (int t = 0; t < 3; t++) {
        v[t].resize(n);
        for (auto &x : v[t]) scanf("%lld", &x);
    }
    if (n == 1) {
        printf("%lld\n", v[0][0]);
        return 0;
    }
    // Best settled prefix: dp0 if the right neighbor of node i is deployed before it, dp1 otherwise.
    ll dp0 = v[1][0], dp1 = v[0][0];
    for (int i = 1; i < n - 1; i++) {
        ll n0 = max(dp0 + v[1][i], dp1 + v[2][i]);
        ll n1 = max(dp0 + v[0][i], dp1 + v[1][i]);
        dp0 = n0, dp1 = n1;
    }
    printf("%lld\n", max(dp0 + v[0][n - 1], dp1 + v[1][n - 1]));
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        // v[0] = no, v[1] = one, v[2] = both (profit by number of earlier neighbors).
        long[][] v = new long[3][n];
        for (int t = 0; t < 3; t++)
            for (int i = 0; i < n; i++) v[t][i] = nextLong();
        if (n == 1) {
            System.out.println(v[0][0]);
            return;
        }
        // Best settled prefix: dp0 if the right neighbor of node i is deployed before it, dp1 otherwise.
        long dp0 = v[1][0], dp1 = v[0][0];
        for (int i = 1; i < n - 1; i++) {
            long n0 = Math.max(dp0 + v[1][i], dp1 + v[2][i]);
            long n1 = Math.max(dp0 + v[0][i], dp1 + v[1][i]);
            dp0 = n0;
            dp1 = n1;
        }
        System.out.println(Math.max(dp0 + v[0][n - 1], dp1 + v[1][n - 1]));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// v[0] = no, v[1] = one, v[2] = both (profit by number of earlier neighbors).
	var v [3][]int64
	for t := 0; t < 3; t++ {
		v[t] = make([]int64, n)
		for i := range v[t] {
			v[t][i] = nextInt()
		}
	}
	if n == 1 {
		fmt.Println(v[0][0])
		return
	}
	// Best settled prefix: dp0 if the right neighbor of node i is deployed before it, dp1 otherwise.
	dp0, dp1 := v[1][0], v[0][0]
	for i := 1; i < n-1; i++ {
		dp0, dp1 = max(dp0+v[1][i], dp1+v[2][i]), max(dp0+v[0][i], dp1+v[1][i])
	}
	fmt.Println(max(dp0+v[0][n-1], dp1+v[1][n-1]))
}
